"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "../hooks/usePrefersReducedMotion";

/**
 * 숨결 원 — the breathing background.
 *
 * Three concentric translucent circles (paper-warm at falling alpha) that
 * breathe on a slow 12s cycle (scale 1 → 1.06, ease-in-out, infinite
 * alternate) and drift with the pointer (pointer-parallax): each layer's
 * translate is lerped toward the pointer offset, weighted by --st-depth
 * so the farthest layer moves least. The whole stack sits behind the
 * content at z-index 0 and is decorative (aria-hidden, role="img" with a
 * bilingual description).
 *
 * Discipline:
 * - Pointer parallax runs in a single rAF loop, lerped (0.06/frame) and
 *   capped to a small radius, transform-only; offscreen or hidden tab →
 *   the loop pauses and the circles settle to rest.
 * - Reduced motion: the breathing keyframe is removed and the parallax
 *   hook never starts; the circles sit still, present, calm.
 * - Touch: there is no hover dependency — the circles breathe on their
 *   own; pointer drift is a progressive enhancement that simply does not
 *   engage on a coarse pointer.
 *
 * The element is purely decorative: aria-hidden hides it from assistive
 * tech, and a visually-hidden description satisfies the scene's labeling
 * without adding noise.
 */
export default function BreathCircle() {
  const reduced = usePrefersReducedMotion();
  const stackRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const el = stackRef.current;
    if (!el) return;
    if (reduced) return;

    // Only fine pointers contribute parallax; coarse pointers (touch)
    // leave the circles to breathe on their own.
    if (!window.matchMedia("(pointer: fine)").matches) return;

    let raf = 0;
    // current rendered offsets, lerped toward target
    let cx = 0;
    let cy = 0;
    // target offset derived from pointer
    let tx = 0;
    let ty = 0;

    const onPointer = (e: PointerEvent) => {
      const w = window.innerWidth || 1;
      const h = window.innerHeight || 1;
      // -1..1 from center, then scaled per-layer by --st-depth in CSS.
      tx = ((e.clientX / w) - 0.5) * 2;
      ty = ((e.clientY / h) - 0.5) * 2;
    };

    const frame = () => {
      raf = requestAnimationFrame(frame);
      cx += (tx - cx) * 0.06;
      cy += (ty - cy) * 0.06;
      // -12% .. +12% of viewport, capped by the lerp + clamp in CSS.
      el.style.setProperty("--st-px", (cx * 12).toFixed(3));
      el.style.setProperty("--st-py", (cy * 12).toFixed(3));
    };

    const start = () => {
      if (raf) return;
      raf = requestAnimationFrame(frame);
    };
    const stop = () => {
      if (!raf) return;
      cancelAnimationFrame(raf);
      raf = 0;
    };

    const onVisibility = () => {
      if (document.hidden) stop();
      else start();
    };

    window.addEventListener("pointermove", onPointer, { passive: true });
    document.addEventListener("visibilitychange", onVisibility);
    start();

    return () => {
      window.removeEventListener("pointermove", onPointer);
      document.removeEventListener("visibilitychange", onVisibility);
      stop();
    };
  }, [reduced]);

  return (
    <div
      ref={stackRef}
      className="stretch-breath"
      aria-hidden="true"
      role="img"
      aria-label="숨결 원 — 배경에서 천천히 부풀었다 가라앉는 세 겹의 옅은 원. Three faint concentric circles breathing slowly behind the page."
    >
      <span className="stretch-breath__layer stretch-breath__layer--1" />
      <span className="stretch-breath__layer stretch-breath__layer--2" />
      <span className="stretch-breath__layer stretch-breath__layer--3" />
    </div>
  );
}

"use client";

import type { CSSProperties, ReactNode } from "react";
import { usePrefersReducedMotion } from "../hooks/usePrefersReducedMotion";
import { useStretchScroll } from "../hooks/useStretchScroll";

/**
 * 늘어나는 자리 — the kinetic-typography signature.
 *
 * A tall spacer pins a scene for the length of the sequence; as the reader
 * scrolls, each pose's name writes itself and its headline glyphs
 * elongate vertically (scaleY grows with scrub) — the type reaching the
 * way a body reaches in a held pose. Four poses, each a full reach:
 *   산(山)  · Earth   — feet down, spine up
 *   하늘(하늘) · Sky   — arms long, eyes soft
 *   나무(나무) · Tree  — root and reach at once
 *   숨(숨)  · Breath  — the closing, everything lengthening into one exhale
 *
 * The pinned scene stacks all four poses; only the one whose 0.25-wide
 * scrub band is active is shown, via opacity tied to --st-scrub. The
 * active pose's own sub-scrub (a 0→1 remapped from its band) drives the
 * scaleY stretch and the name's per-glyph write.
 *
 * Geometry is set per-pose through CSS custom properties so the logic is
 * in the stylesheet (readable, scrubbable), not in JS layout:
 *   --st-p0..3: the 0.25-wide band each pose occupies in [0,1]
 *   --st-scrub: the overall sequence scrub (0→1) from useStretchScroll
 * Everything is transform/opacity only. The pin is position: sticky.
 * With reduced motion or no JS, --st-scrub defaults to 1 → every pose is
 * at full reach, fully written; the sequence reads as a finished poster.
 */

type Pose = {
  /** local id, used as a React key and for aria wiring */
  id: string;
  /** the 0.25-wide band this pose owns in the overall scrub */
  start: number;
  /** korean wordmark — the head of the pose */
  koName: string;
  /** latin wordmark — the second voice */
  latin: string;
  /** ordinal label, bilingual */
  ordinal: { ko: string; en: string };
  /** the en one-line gloss */
  gloss: string;
  /** long ko instruction, the body of the pose */
  bodyKo: string;
  /** long en instruction, the body of the pose */
  bodyEn: string;
  /** the breath cue for this pose */
  breath: { ko: string; en: string };
};

const POSES: Pose[] = [
  {
    id: "earth",
    start: 0,
    koName: "산",
    latin: "EARTH",
    ordinal: { ko: "첫 자세", en: "Pose I" },
    gloss: "feet down, spine up",
    bodyKo:
      "발끝으로 땅을 누르고, 정수리로 하늘을 민다. 사이에 낀 온몸이 제 할 일을 찾을 때까지, 우리는 아무것도 더하지 않는다.",
    bodyEn:
      "Press the ground down with the soles; push the sky up with the crown. Until the body caught between them finds its own work, we add nothing.",
    breath: { ko: "네 박자로 들이쉬고, 여섯 박자로 내쉰다.", en: "Inhale four, exhale six." },
  },
  {
    id: "sky",
    start: 0.25,
    koName: "하늘",
    latin: "SKY",
    ordinal: { ko: "둘째 자세", en: "Pose II" },
    gloss: "arms long, eyes soft",
    bodyKo:
      "팔을 길게 뻗되 힘을 주지 않는다. 눈은 가는 곳을 보되, 잡으려 하지 않는다. 뻗는 일과 놓는 일이 한 자세 안에서 만난다.",
    bodyEn:
      "Reach the arms long without forcing them. Let the eyes follow where they go without trying to hold it. The reaching and the releasing meet inside one pose.",
    breath: { ko: "들이쉬며 길어지고, 내쉬며 더 길어진다.", en: "Lengthen on the inhale, lengthen further on the exhale." },
  },
  {
    id: "tree",
    start: 0.5,
    koName: "나무",
    latin: "TREE",
    ordinal: { ko: "셋째 자세", en: "Pose III" },
    gloss: "root and reach at once",
    bodyKo:
      "한 발은 뿌리가 되고, 다른 발은 가지가 된다. 가만히 서 있으면서도 자라는 일을 배우는 자세. 흔들림은 흔들리지 않음이 아니다.",
    bodyEn:
      "One foot becomes a root; the other becomes a branch. The pose where you stand still and learn to grow at once. Sway is not the opposite of steadiness.",
    breath: { ko: "흔들릴 때 숨이 버틴다.", en: "When you sway, the breath holds." },
  },
  {
    id: "breath",
    start: 0.75,
    koName: "숨",
    latin: "BREATH",
    ordinal: { ko: "마지막 자세", en: "Pose IV" },
    gloss: "everything lengthens into one exhale",
    bodyKo:
      "눕지 않고 눕는 자세. 등이 바닥을 알아가는 동안, 온몸이 천천히 풀려 가장 긴 버전의 내가 된다. 끝맺음이 아니라, 다 잘 때까지.",
    bodyEn:
      "The pose of lying down without lying down. While the back learns the floor, the whole body slowly gives way until it is the longest version of you. Not an ending — until everything has let go.",
    breath: { ko: "아무것도 하지 말고, 숨만 길게.", en: "Do nothing. Only let the breath run long." },
  },
];

/** Split a string into per-glyph aria-hidden spans; the visible label
 * lives on the container so assistive tech reads one word, never the
 * staggered spans. */
function Glyphs({
  text,
  base,
}: {
  text: string;
  base: string;
}): ReactNode {
  return (
    <>
      {Array.from(text).map((ch, i) => (
        <span
          key={`${base}-${ch}-${i}`}
          aria-hidden="true"
          className="stretch-glyph"
          style={{ "--st-gi": i } as CSSProperties}
        >
          {ch}
        </span>
      ))}
    </>
  );
}

/** One pose card, absolutely stacked in the pinned scene; its visibility
 *  and stretch are driven by its band of the overall scrub. */
function PoseCard({ pose, index }: { pose: Pose; index: number }) {
  const bandStart = pose.start;
  // Each pose owns a 0.25-wide band of [0,1]; --st-p0..3 declares them so
  // the stylesheet can map the global scrub onto a per-pose sub-scrub.
  return (
    <article
      className="stretch-pose"
      aria-label={`${pose.ordinal.ko} — ${pose.koName} · ${pose.latin}`}
      style={
        {
          "--st-pi": index,
          "--st-p0": bandStart,
          "--st-p1": bandStart + 0.25,
        } as CSSProperties
      }
    >
      <p className="stretch-pose__ordinal" aria-hidden="true">
        <span lang="ko">{pose.ordinal.ko}</span> · {pose.ordinal.en}
      </p>

      <h3
        className="stretch-pose__name"
        lang="ko"
        aria-label={`${pose.koName} · ${pose.latin}`}
      >
        <span className="stretch-pose__name-ko" aria-hidden="true">
          <Glyphs text={pose.koName} base={pose.id} />
        </span>
        <span className="stretch-pose__name-latin" aria-hidden="true">
          <Glyphs text={pose.latin} base={`${pose.id}-l`} />
        </span>
      </h3>

      <div className="stretch-pose__body" data-reveal>
        <p className="stretch-pose__gloss">
          <em>{pose.gloss}</em>
        </p>
        <p className="stretch-pose__p stretch-pose__p--ko" lang="ko">
          {pose.bodyKo}
        </p>
        <p className="stretch-pose__p stretch-pose__p--en">
          {pose.bodyEn}
        </p>
        <p className="stretch-pose__breath">
          <span className="stretch-pose__breath-cue" lang="ko">숨</span>{" "}
          <span lang="ko">{pose.breath.ko}</span>{" "}
          <em>— {pose.breath.en}</em>
        </p>
      </div>
    </article>
  );
}

export default function PoseSequence() {
  const reduced = usePrefersReducedMotion();
  const spacerRef = useStretchScroll<HTMLDivElement>(reduced);

  return (
    <section
      id="st-sequence"
      className="stretch-sequence"
      aria-labelledby="st-sequence-title"
    >
      <header className="stretch-sequence__head" data-reveal>
        <p className="stretch-kicker">
          <span lang="ko">네 개의 자세</span> · Four Poses, Held
        </p>
        <h2 id="st-sequence-title" className="stretch-sequence__title" lang="ko">
          늘어나는 자리
        </h2>
        <p className="stretch-sequence__sub">
          The Place of Lengthening — scroll slowly; the names write themselves as you hold
        </p>
      </header>

      {/* The tall spacer is the scrub target; the pinned scene lives inside. */}
      <div ref={spacerRef} className="stretch-sequence__spacer">
        <div className="stretch-sequence__pin">
          {/* the long clay line that grows across the whole sequence */}
          <div className="stretch-sequence__rail" aria-hidden="true">
            <span className="stretch-sequence__rail-fill" />
            <span className="stretch-sequence__rail-ticks">
              {POSES.map((p) => (
                <span key={`tick-${p.id}`} className="stretch-sequence__tick">
                  <span className="stretch-sequence__tick-label">
                    {p.latin}
                  </span>
                </span>
              ))}
            </span>
          </div>

          <div className="stretch-sequence__scene">
            {POSES.map((pose, i) => (
              <PoseCard key={pose.id} pose={pose} index={i} />
            ))}
          </div>

          {/* a fixed breath counter at the corner of the pinned scene */}
          <p className="stretch-sequence__count" aria-hidden="true">
            <span className="stretch-sequence__count-n">01</span>
            <span className="stretch-sequence__count-of"> / 04</span>
          </p>
        </div>
      </div>

      <p className="stretch-sequence__after" data-reveal lang="ko">
        네 자세를 지나면, 몸은 페이지보다 길다.
      </p>
    </section>
  );
}

// Self-hosted via @fontsource — no build-time Google Fonts fetch.
import "@fontsource/cormorant-garamond";
import "@fontsource/noto-serif-kr";

export const cormorantGaramond = { variable: "" };
export const notoSerifKR = { variable: "" };

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";

/**
 * Reveals descendants marked with [data-reveal] as they enter the viewport,
 * by adding an `is-visible` class. Pre-reveal states (a quiet rise for
 * text, 18px → 0) live in styles.css and are gated behind the `.stretch-js`
 * root class, so the whole studio site is plainly readable when JavaScript
 * never runs — a wellness page must degrade to a calm, complete document.
 *
 * Elements that intersect in the same observer batch are staggered 90ms
 * apart via transition-delay, a touch slower than the default — breath,
 * not snap.
 */
export function useReveal<T extends HTMLElement>(disabled: boolean) {
  const rootRef = useRef<T | null>(null);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const targets = Array.from(
      root.querySelectorAll<HTMLElement>("[data-reveal]"),
    );

    if (disabled || !("IntersectionObserver" in window)) {
      for (const el of targets) el.classList.add("is-visible");
      return;
    }

    const io = new IntersectionObserver(
      (hits) => {
        let batch = 0;
        for (const hit of hits) {
          if (!hit.isIntersecting) continue;
          const el = hit.target as HTMLElement;
          el.style.transitionDelay = `${batch * 90}ms`;
          el.classList.add("is-visible");
          io.unobserve(el);
          batch += 1;
        }
      },
      { threshold: 0.12, rootMargin: "0px 0px -8% 0px" },
    );
    for (const el of targets) io.observe(el);
    return () => io.disconnect();
  }, [disabled]);

  return rootRef;
}

"use client";

import { useEffect, useRef } from "react";

/**
 * Drives a 0→1 scroll-progress for a section, written to the element as a
 * `--st-progress` custom property. Unlike useStretchScrub (which maps a
 * range onto the pinned pose-sequence), this is the general-purpose
 * page-relative progress used by the long clay pose-divider that grows
 * across the whole sequence.
 *
 * Discipline:
 * - One getBoundingClientRect read, one custom-property write per frame
 *   (read before write, no layout thrash).
 * - Raw progress is lerp-smoothed with a dt-normalized factor (slower than
 *   the default — calm catch-up) so 120Hz and 60Hz scrub at the same rate.
 * - An IntersectionObserver starts/stops the loop; offscreen = zero frames.
 * - Disabled (reduced motion) or never mounted (no JS): the element keeps
 *   its CSS default `var(--st-progress, 1)` — every driven surface is
 *   already at its finished, fully-stretched end state.
 */
export function useScrollProgress<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    if (disabled) {
      el.style.setProperty("--st-progress", "1");
      return;
    }

    let raf = 0;
    let last = 0;
    let value: number | null = null;

    const frame = (now: number) => {
      raf = requestAnimationFrame(frame);
      const dt = Math.min(Math.max(now - last, 1), 48);
      last = now;

      const rect = el.getBoundingClientRect();
      const vh = window.innerHeight || 1;

      // Progress begins when the section top reaches 80% of the viewport
      // and completes when its bottom leaves 20% — a generous, calm span.
      const span = Math.max(rect.height + vh * 0.6, 1);
      const raw = (vh * 0.8 - rect.top) / span;
      const target = Math.min(1, Math.max(0, raw));

      if (value === null) {
        value = target;
      } else {
        value += (target - value) * (1 - Math.pow(0.88, dt / 16.7));
        if (Math.abs(target - value) < 0.0005) value = target;
      }

      el.style.setProperty("--st-progress", value.toFixed(4));
    };

    const start = () => {
      if (raf) return;
      last = performance.now();
      raf = requestAnimationFrame(frame);
    };
    const stop = () => {
      if (!raf) return;
      cancelAnimationFrame(raf);
      raf = 0;
    };

    if (!("IntersectionObserver" in window)) {
      start();
      return stop;
    }

    const io = new IntersectionObserver(
      (hits) => {
        for (const hit of hits) {
          if (hit.isIntersecting) start();
          else stop();
        }
      },
      { rootMargin: "30% 0px 30% 0px" },
    );
    io.observe(el);

    return () => {
      stop();
      io.disconnect();
    };
  }, [disabled]);

  return ref;
}

"use client";

import { useEffect, useRef } from "react";

/**
 * The pinned pose-sequence's engine. Writes a `--st-scrub` custom property
 * (0→1) onto the pinned scene's element, measured against the *tall spacer*
 * that wraps it: as the reader scrolls through the spacer, the pinned
 * headline of the active pose elongates (scaleY grows) and its name writes
 * itself, exactly as far as the reader has scrolled — then the scene
 * releases when the spacer ends.
 *
 * This is the kinetic-typography signature: the type stretches vertically
 * like a body reaching in a pose, driven by how long you hold the scroll.
 * Slow lerp, long reach, calm.
 *
 * Discipline:
 * - One read (the spacer's rect), one write (the custom property) per
 *   frame — read before write, no layout thrash.
 * - Raw progress is lerp-smoothed with a dt-normalized, deliberately slow
 *   factor (0.88 → half-life ≈ 5.4 frames) so the catch-up feels like a
 *   held breath rather than a snap.
 * - An IntersectionObserver starts/stops the loop; an offscreen sequence
 *   costs zero frames. The loop also pauses when the tab is hidden.
 * - Disabled (reduced motion) or never mounted (no JS): CSS defaults
 *   `--st-scrub` to 1 — every pose is at full reach, fully written, a
 *   finished static page.
 */
export function useStretchScroll<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    if (disabled) {
      el.style.setProperty("--st-scrub", "1");
      return;
    }

    let raf = 0;
    let last = 0;
    let value: number | null = null;

    const frame = (now: number) => {
      raf = requestAnimationFrame(frame);
      const dt = Math.min(Math.max(now - last, 1), 48);
      last = now;

      // The tall spacer IS the element we measure; the pinned scene sits
      // inside it. The scrub runs from "spacer top at 18vh" to "spacer
      // bottom at 82vh" — a long, calm span that lets each pose breathe.
      const rect = el.getBoundingClientRect();
      const vh = window.innerHeight || 1;
      const span = Math.max(rect.height - vh * 0.64, 1);
      const raw = (vh * 0.18 - rect.top) / span;
      const target = Math.min(1, Math.max(0, raw));

      if (value === null) {
        value = target;
      } else {
        value += (target - value) * (1 - Math.pow(0.88, dt / 16.7));
        if (Math.abs(target - value) < 0.0005) value = target;
      }

      el.style.setProperty("--st-scrub", value.toFixed(4));
    };

    const start = () => {
      if (raf) return;
      last = performance.now();
      raf = requestAnimationFrame(frame);
    };
    const stop = () => {
      if (!raf) return;
      cancelAnimationFrame(raf);
      raf = 0;
    };

    const onVisibility = () => {
      if (document.hidden) stop();
      else {
        // Re-evaluate via the observer the next tick.
        start();
      }
    };

    if (!("IntersectionObserver" in window)) {
      start();
      document.addEventListener("visibilitychange", onVisibility);
      return () => {
        stop();
        document.removeEventListener("visibilitychange", onVisibility);
      };
    }

    const io = new IntersectionObserver(
      (hits) => {
        for (const hit of hits) {
          if (hit.isIntersecting && !document.hidden) start();
          else stop();
        }
      },
      { rootMargin: "20% 0px 20% 0px" },
    );
    io.observe(el);
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      stop();
      io.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, [disabled]);

  return ref;
}

"use client";

import { useEffect, useRef } from "react";
import "./styles.css";
import { cormorantGaramond, notoSerifKR } from "./fonts";
import Hero from "./components/Hero";
import PoseSequence from "./components/PoseSequence";
import BreathCircle from "./components/BreathCircle";
import StudioFooter from "./components/StudioFooter";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";
import { useReveal } from "./hooks/useReveal";

/**
 * 늘어남 STRETCH — A Studio That Breathes.
 * A bilingual (KO-first) yoga & wellness studio site where the typography
 * itself stretches: the hero wordmark reaches on mount, the pinned
 * pose-sequence elongates each asana's name as you scroll, and
 * breathing-circle backgrounds drift behind it all. The product of the
 * studio — lengthening, breath, calm — is the motion of the page.
 *
 * `.stretch-js` is added on mount so every scroll-driven style is
 * JS-gated: with JavaScript disabled the whole studio is simply
 * readable — wordmark stretched, poses at full reach, names written, a
 * finished static poster.
 */
export default function StretchPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>(reduced);

  useEffect(() => {
    // Imperative on purpose: the class signals JS is alive to CSS, and it
    // never changes once set.
    rootRef.current?.classList.add("stretch-js");
    window.parent?.postMessage({ type: "oneshot:ready", slug: "stretch" }, "*");
  }, []);

  return (
    <div
      id="stretch-top"
      ref={rootRef}
      className={`${notoSerifKR.variable} ${cormorantGaramond.variable} stretch-root`}
    >
      <BreathCircle />
      <div ref={revealRef} className="stretch-issue">
        <Hero />
        <main>
          <PoseSequence />
        </main>
        <StudioFooter />
      </div>
    </div>
  );
}

/* ==========================================================================
   늘어남 STRETCH — A Studio That Breathes · No. 01
   kinetic-typography · light/calm/breathful · type that reaches on scroll
   Scoped by convention to .stretch-root; classes prefixed stretch-.
   Distinct from TYPEWAVE: where the 1st entry of this family is dark /
   energetic / waveform-driven, STRETCH is warm off-white, slow, and
   stretches type *vertically* — the lengthening the studio teaches.
   ========================================================================== */

.stretch-root {
  /* -- palette ------------------------------------------------------------ */
  --st-paper: #f7f3ec;             /* the warm off-white page — calm lives here */
  --st-paper-warm: #fbf8f2;        /* breath-circle fills, plate panels */
  --st-ink: #2f2a24;               /* text ink — 12.85:1 on paper (AAA) */
  --st-ink-soft: rgba(47, 42, 36, 0.7); /* ≈ #6b6660 — 5.14:1, secondary text */
  --st-clay: #c97b5a;              /* display/large only — 2.94:1; the wordmark fill, rings */
  --st-clay-deep: #a85e3f;         /* readable clay — 4.38:1; kickers, ordinals, links, focus */
  --st-sage: #8a9a7b;              /* rules ONLY — 2.72:1; never text */
  --st-sage-deep: #5f6f50;         /* readable sage — 4.90:1; the breath cue */
  --st-rule: rgba(138, 154, 123, 0.5);        /* derived: standard sage hairline */
  --st-rule-faint: rgba(138, 154, 123, 0.28); /* derived: faint dividers */
  --st-shadow: rgba(47, 42, 36, 0.10);        /* derived: soft panel shadow */

  /* -- type ---------------------------------------------------------------- */
  --st-font-latin: var(--font-cormorant), "Cormorant Garamond", Georgia, serif;
  --st-font-kr: var(--font-noto-kr), "Noto Serif KR", serif;
  /* Cormorant first: Latin resolves there, Hangul falls through into Noto Serif KR */
  --st-font-stack: var(--font-cormorant), var(--font-noto-kr), Georgia, serif;

  /* -- motion -------------------------------------------------------------- */
  --st-ease-breathe: cubic-bezier(0.45, 0, 0.2, 1);  /* slow inhale, longer exhale */
  --st-ease-stretch: cubic-bezier(0.22, 1, 0.36, 1); /* long reach past midpoint */
  --st-ease-recoil: cubic-bezier(0.34, 1.24, 0.4, 1);/* ~12% overshoot: wordmark settle only */
  --st-reveal-ms: 760ms;

  /* Scrub defaults: 1 = every pose at full reach, every name written.
     JS lowers these per-section; reduced-motion and no-JS never touch them. */
  --st-scrub: 1;
  --st-progress: 1;

  /* Pointer-parallax offset, set by BreathCircle's rAF (clamped in layers). */
  --st-px: 0;
  --st-py: 0;

  position: relative;
  min-height: 100vh;
  min-height: 100svh;
  background: var(--st-paper);
  color: var(--st-ink);
  font-family: var(--st-font-stack);
  font-size: clamp(16px, 0.45vw + 14px, 19px);
  line-height: 1.8;
  overflow-x: hidden;
  overflow-x: clip;
}

/* Korean is the first language of this studio: Noto Serif KR, keep-all line
   breaking, a touch of negative tracking, looser leading. */
.stretch-root :lang(ko) {
  font-family: var(--st-font-kr);
  letter-spacing: -0.005em;
  word-break: keep-all;
  line-height: 2.0;
}

/* Clay selection, scoped to the entry root: clay bg, ink text (4.38:1, AA) */
.stretch-root ::selection {
  background: var(--st-clay-deep);
  color: var(--st-paper);
}

/* Keyboard focus: a clay-deep ring, offset like a held edge */
.stretch-root :focus-visible {
  outline: 2px solid var(--st-clay-deep);
  outline-offset: 3px;
  border-radius: 1px;
}

.stretch-issue {
  position: relative;
  z-index: 1;
}

/* ==========================================================================
   Links — the soft clay underline that reaches from the left
   A static sage hairline is always present (touch users never lose the
   affordance); a clay-deep underline grows in (scaleX 0 → 1, from the
   left) on hover/focus through the breathe ease. Pure CSS: no JS.
   ========================================================================== */

.stretch-link {
  position: relative;
  display: inline-block;
  color: var(--st-ink);
  text-decoration: none;
  border-bottom: 1px solid var(--st-rule);
  padding-bottom: 2px;
  transition: color 300ms var(--st-ease-breathe);
}

.stretch-link::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 1.6px;
  background: var(--st-clay-deep);
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 220ms var(--st-ease-breathe);
}

.stretch-link:hover,
.stretch-link:focus-visible {
  color: var(--st-clay-deep);
}

.stretch-link:hover::after,
.stretch-link:focus-visible::after {
  transform: scaleX(1);
  transition: transform 520ms var(--st-ease-breathe);
}

/* The cover CTA: a larger, more inviting reach */
.stretch-cover__cta {
  position: relative;
  display: inline-block;
  color: var(--st-ink);
  text-decoration: none;
  font-family: var(--st-font-latin);
  font-size: clamp(1.05rem, 1.4vw, 1.25rem);
  padding-bottom: 4px;
  border-bottom: 1px solid var(--st-rule);
  transition: color 300ms var(--st-ease-breathe);
}

.stretch-cover__cta::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 2px;
  background: var(--st-clay-deep);
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 220ms var(--st-ease-breathe);
}

.stretch-cover__cta:hover,
.stretch-cover__cta:focus-visible {
  color: var(--st-clay-deep);
}

.stretch-cover__cta:hover::after,
.stretch-cover__cta:focus-visible::after {
  transform: scaleX(1);
  transition: transform 640ms var(--st-ease-stretch);
}

/* ==========================================================================
   Breath circles — the breathing background (pointer-parallax + 12s cycle)
   Three translucent layers, paper-warm at falling alpha, breathing on a
   slow alternate cycle and drifting with the pointer. Purely decorative.
   ========================================================================== */

.stretch-breath {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}

.stretch-breath__layer {
  position: absolute;
  left: 50%;
  top: 50%;
  border-radius: 50%;
  /* pointer drift: translate is clamped via the calc, depth via --st-depth */
  transform: translate(
    calc(-50% + (var(--st-px) * var(--st-depth, 0)) * 1px),
    calc(-50% + (var(--st-py) * var(--st-depth, 0)) * 1px)
  ) scale(var(--st-scale, 1));
  animation: st-breath 12s var(--st-ease-breathe) infinite alternate;
  will-change: transform;
}

.stretch-breath__layer--1 {
  width: min(140vw, 140vh);
  height: min(140vw, 140vh);
  background: rgba(251, 248, 242, 0.92);
  --st-depth: 0.4;
  --st-scale: 1;
}

.stretch-breath__layer--2 {
  width: min(92vw, 92vh);
  height: min(92vw, 92vh);
  background: rgba(201, 123, 90, 0.07);
  --st-depth: 0.7;
  --st-scale: 1;
  animation-delay: -2s;
}

.stretch-breath__layer--3 {
  width: min(52vw, 52vh);
  height: min(52vw, 52vh);
  background: rgba(138, 154, 123, 0.06);
  --st-depth: 1;
  --st-scale: 1;
  animation-delay: -4s;
}

@keyframes st-breath {
  from {
    transform: translate(
      calc(-50% + (var(--st-px) * var(--st-depth, 0)) * 1px),
      calc(-50% + (var(--st-py) * var(--st-depth, 0)) * 1px)
    ) scale(calc(var(--st-scale, 1) * 1));
  }
  to {
    transform: translate(
      calc(-50% + (var(--st-px) * var(--st-depth, 0)) * 1px),
      calc(-50% + (var(--st-py) * var(--st-depth, 0)) * 1px)
    ) scale(calc(var(--st-scale, 1) * 1.06));
  }
}

/* ==========================================================================
   Kicker — the recurring ornament: a small-tracked bilingual label with a
   clay-deep en-dash lead
   ========================================================================== */

.stretch-kicker {
  margin: 0 0 1.4rem;
  font-family: var(--st-font-latin);
  font-size: 0.72rem;
  letter-spacing: 0.26em;
  text-transform: uppercase;
  color: var(--st-clay-deep);
}

.stretch-kicker::before {
  content: "—";
  display: inline-block;
  margin-right: 0.6em;
  color: var(--st-clay);
}

/* ==========================================================================
   Cover / Hero — the wordmark that reaches
   STRETCH split into per-glyph spans (aria-hidden behind the h1 label),
   each rising on mount and gently overshooting (scaleY 0.78 → 1.06 → 1).
   The clay fill writes in after the rise. 한국어 늘어 sits in dialogue,
   set half a step quieter. All choreography gated behind .stretch-js.
   ========================================================================== */

.stretch-cover {
  position: relative;
  min-height: 100vh;
  min-height: 100svh;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: clamp(2rem, 5vh, 3.5rem) clamp(1.25rem, 5vw, 5rem)
    clamp(2.5rem, 6vh, 4rem);
}

.stretch-cover__folio {
  margin: 0;
  font-family: var(--st-font-latin);
  font-size: 0.72rem;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--st-ink-soft);
}

.stretch-cover__id {
  margin: auto 0;
}

/* The wordmark: latin row, then korean row beneath, both stretching. */
.stretch-wordmark {
  display: flex;
  flex-direction: column;
  gap: clamp(0.4rem, 1.5vh, 1rem);
  margin: 0 0 clamp(1.5rem, 3vh, 2.5rem);
  font-weight: 500;
  line-height: 0.92;
}

.stretch-wordmark__latin {
  display: flex;
  font-family: var(--st-font-latin);
  font-size: clamp(4.5rem, 19vw, 16rem);
  letter-spacing: 0.01em;
  color: var(--st-ink);
}

.stretch-wordmark__ko {
  display: flex;
  font-family: var(--st-font-kr);
  font-weight: 700;
  font-size: clamp(2.2rem, 8.5vw, 6.5rem);
  letter-spacing: -0.01em;
  color: var(--st-clay);
}

.stretch-wordmark__ch {
  display: inline-block;
  transform-origin: 50% 78%;
  /* fill is a clip reveal from the baseline; gated behind .stretch-js */
}

/* The clay fill writes in across the whole wordmark on mount. */
.stretch-wordmark__ko::after {
  content: "";
}

/* Reach + settle keyframe: per-glyph stagger by --st-gi. */
@keyframes st-reach {
  0% {
    opacity: 0;
    transform: scaleY(0.78) translateY(0.12em);
  }
  60% {
    opacity: 1;
    transform: scaleY(1.06) translateY(-0.02em);
  }
  100% {
    opacity: 1;
    transform: scaleY(1) translateY(0);
  }
}

.stretch-cover__deck {
  margin: clamp(1.5rem, 4vh, 2.5rem) 0 1.2rem;
  font-family: var(--st-font-latin);
  font-style: italic;
  font-size: clamp(1.05rem, 1.6vw, 1.4rem);
  color: var(--st-ink-soft);
}

.stretch-cover__rule {
  height: 1px;
  width: 100%;
  max-width: 22rem;
  background: var(--st-rule);
  transform-origin: left center;
  margin: 0 0 1.4rem;
}

.stretch-cover__issue {
  margin: 0;
  font-family: var(--st-font-kr);
  font-size: clamp(0.85rem, 1.1vw, 0.98rem);
  letter-spacing: 0.01em;
  color: var(--st-ink-soft);
  max-width: 38rem;
}

.stretch-cover__foot {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  align-items: flex-start;
}

.stretch-cover__begin {
  margin: 0;
}

.stretch-cover__epigraph {
  margin: 0;
  font-family: var(--st-font-latin);
  font-size: clamp(0.95rem, 1.2vw, 1.1rem);
  color: var(--st-ink-soft);
  max-width: 34rem;
}

.stretch-cover__epigraph em {
  font-style: italic;
}

/* JS-gated cover choreography: rise + reach per glyph, rule grow. */
.stretch-js .stretch-wordmark__ch {
  opacity: 0;
  animation: st-reach 1400ms var(--st-ease-breathe) forwards;
  animation-delay: calc(120ms + var(--st-gi) * 90ms);
}

.stretch-js .stretch-cover__rule {
  transform: scaleX(0);
  animation: st-rule-grow 900ms var(--st-ease-stretch) forwards;
  animation-delay: 780ms;
}

@keyframes st-rule-grow {
  from {
    transform: scaleX(0);
  }
  to {
    transform: scaleX(1);
  }
}

/* ==========================================================================
   Pose sequence — the kinetic-typography signature (scroll-scrub-pinned)
   A tall spacer pins a scene; --st-scrub (0→1, from useStretchScroll)
   drives everything. Four poses each own a 0.25-wide band; the active
   pose's name writes itself and its glyphs elongate vertically
   (scaleY 1 → 2.8) — the type reaching like a body in a held pose.
   All geometry in calc() off the per-pose --st-p0/--st-p1 and the global
   --st-scrub. transform/opacity only; pin is position: sticky.
   ========================================================================== */

.stretch-sequence {
  position: relative;
  padding: clamp(5rem, 14vh, 9rem) clamp(1.25rem, 5vw, 5rem)
    clamp(4rem, 10vh, 7rem);
}

.stretch-sequence__head {
  max-width: 44rem;
  margin: 0 0 clamp(3rem, 8vh, 6rem);
}

.stretch-sequence__title {
  margin: 0 0 0.6rem;
  font-family: var(--st-font-kr);
  font-weight: 700;
  font-size: clamp(2.2rem, 5.5vw, 4rem);
  line-height: 1.1;
  color: var(--st-ink);
}

.stretch-sequence__sub {
  margin: 0;
  font-family: var(--st-font-latin);
  font-style: italic;
  font-size: clamp(1rem, 1.4vw, 1.2rem);
  color: var(--st-ink-soft);
}

/* The tall spacer: defines how long the sequence is pinned. ~2.6 viewports
   per pose × 4 ≈ tall; calm, not greedy. */
.stretch-sequence__spacer {
  position: relative;
  height: clamp(220vh, 320vh, 360vh);
}

.stretch-sequence__pin {
  position: sticky;
  top: 0;
  height: 100vh;
  height: 100svh;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-content: center;
  padding: clamp(2rem, 5vh, 3.5rem) 0;
}

/* The long clay rail that grows across the whole sequence. */
.stretch-sequence__rail {
  position: absolute;
  left: 0;
  right: 0;
  top: clamp(1.5rem, 4vh, 2.5rem);
  height: 2px;
  background: var(--st-rule-faint);
}

.stretch-sequence__rail-fill {
  position: absolute;
  inset: 0;
  background: var(--st-clay);
  transform: scaleX(0);
  transform-origin: left center;
}

.stretch-sequence__spacer .stretch-sequence__rail-fill {
  transform: scaleX(var(--st-scrub, 1));
}

.stretch-sequence__rail-ticks {
  position: absolute;
  inset: 0;
  display: flex;
  justify-content: space-between;
}

.stretch-sequence__tick {
  position: relative;
  width: 1px;
  height: 8px;
  margin-top: -3px;
  background: var(--st-sage);
}

.stretch-sequence__tick:nth-child(1) {
  margin-left: 0;
}

.stretch-sequence__tick-label {
  position: absolute;
  top: 12px;
  left: 0;
  transform: translateX(-50%);
  font-family: var(--st-font-latin);
  font-size: 0.6rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--st-ink-soft);
  white-space: nowrap;
}

.stretch-sequence__tick:last-child .stretch-sequence__tick-label {
  transform: translateX(-50%);
}

/* The scene holds all four poses, absolutely stacked; visibility by scrub. */
.stretch-sequence__scene {
  position: relative;
  max-width: 46rem;
  margin: clamp(2rem, 6vh, 4rem) auto 0;
  min-height: clamp(18rem, 48vh, 26rem);
}

/* The breath count, pinned to the corner. */
.stretch-sequence__count {
  position: absolute;
  right: 0;
  top: 0;
  margin: 0;
  font-family: var(--st-font-latin);
  font-size: clamp(0.8rem, 1vw, 0.95rem);
  letter-spacing: 0.18em;
  color: var(--st-ink-soft);
}

.stretch-sequence__count-n {
  color: var(--st-clay-deep);
  font-weight: 600;
}

/* Each pose card is stacked; opacity & a small translate track the band. */
.stretch-pose {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: clamp(0.8rem, 2vh, 1.4rem);
  /* visibility computed from the global scrub and this pose's band.
     center c = p0 + 0.125; half-window h = 0.16. The triangle falloff
     1 - |s - c|/h is written as min((s-(c-h))/h, (c+h-s)/h) so it uses
     only min()/clamp() — widely supported since 2020 — and never abs(),
     which is too new to rely on. Verified identical to the abs() form. */
  opacity: clamp(
    0,
    min(
      calc((var(--st-scrub, 1) - (var(--st-p0) - 0.035)) * 6.25),
      calc((var(--st-p0) + 0.285 - var(--st-scrub, 1)) * 6.25)
    ),
    1
  );
  /* a small vertical drift so inactive poses recede gently: how far the
     scrub sits above this pose's center, mapped to a small translate. */
  transform: translateY(
    calc(
      clamp(
        0,
        calc((var(--st-p0) + 0.125 - var(--st-scrub, 1)) * 2),
        1
      ) * -0.6em
    )
  );
  transition: none;
}

/* no-JS / SSR fallback: when .stretch-js is absent the scrub defaults to 1,
   which would leave only the final pose visible. So in the no-JS state we
   flatten the sequence into a static list — every pose fully written, fully
   stretched, stacked in flow with air between (see the rules below). */
.stretch-pose__ordinal {
  margin: 0;
  font-family: var(--st-font-latin);
  font-size: 0.7rem;
  letter-spacing: 0.26em;
  text-transform: uppercase;
  color: var(--st-clay-deep);
}

/* The pose name: korean (big, stretching) then latin (tall, stretching). */
.stretch-pose__name {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin: 0;
  line-height: 0.96;
}

.stretch-pose__name-ko {
  display: flex;
  font-family: var(--st-font-kr);
  font-weight: 700;
  font-size: clamp(3.5rem, 13vw, 9rem);
  color: var(--st-ink);
}

.stretch-pose__name-latin {
  display: flex;
  font-family: var(--st-font-latin);
  font-weight: 500;
  font-size: clamp(1.4rem, 3.5vw, 2.4rem);
  letter-spacing: 0.06em;
  color: var(--st-clay-deep);
}

/* Per-glyph stretch: scaleY grows with the pose's local scrub.
   local scrub ls = clamp((s - p0)/0.25, 0, 1). scaleY = 1 + ls*1.8. */
.stretch-glyph {
  display: inline-block;
  transform-origin: 50% 82%;
  /* CSS cannot clamp a division cleanly without abs; we compute the local
     scrub directly: (s - p0)/(p1 - p0), clamped to [0,1]. p1-p0 = 0.25,
     so divide by 0.25 = multiply by 4. */
  transform: scaleY(
    calc(
      1 +
      clamp(0, calc((var(--st-scrub, 1) - var(--st-p0)) * 4), 1) * 1.8
    )
  );
}

/* Per-glyph write-in: opacity follows the local scrub with a small stagger
   so the name appears to write itself left-to-right as you hold the scroll. */
.stretch-pose__name-ko .stretch-glyph,
.stretch-pose__name-latin .stretch-glyph {
  opacity: clamp(
    0,
    calc((var(--st-scrub, 1) - var(--st-p0) - var(--st-gi) * 0.04) * 8),
    1
  );
}

.stretch-pose__body {
  max-width: 34rem;
}

.stretch-pose__gloss {
  margin: 0 0 1rem;
  font-family: var(--st-font-latin);
  font-style: italic;
  font-size: clamp(1.05rem, 1.5vw, 1.3rem);
  color: var(--st-clay-deep);
}

.stretch-pose__p {
  margin: 0 0 0.9rem;
}

.stretch-pose__p--en {
  font-family: var(--st-font-latin);
  color: var(--st-ink-soft);
  font-size: 0.96em;
}

.stretch-pose__breath {
  margin: 0.4rem 0 0;
  padding-top: 0.9rem;
  border-top: 1px solid var(--st-rule-faint);
  font-size: 0.92rem;
  color: var(--st-ink-soft);
}

.stretch-pose__breath-cue {
  display: inline-block;
  margin-right: 0.5em;
  padding: 0.05em 0.5em;
  border: 1px solid var(--st-sage-deep);
  border-radius: 999px;
  font-family: var(--st-font-kr);
  font-weight: 500;
  font-size: 0.78em;
  color: var(--st-sage-deep);
}

.stretch-sequence__after {
  margin: clamp(3rem, 8vh, 6rem) auto 0;
  max-width: 40rem;
  font-family: var(--st-font-kr);
  font-weight: 500;
  font-size: clamp(1.3rem, 2.6vw, 1.9rem);
  line-height: 1.4;
  color: var(--st-ink);
  text-align: center;
}

/* No-JS / SSR fallback: when .stretch-js is absent (or reduced motion),
   flatten the pinned sequence into a calm static list — every pose fully
   written, fully stretched, stacked with generous air between. The scrub
   defaults to 1, which already gives full stretch; we additionally break
   the absolute stacking so the four poses flow as a document. */
.stretch-root:not(.stretch-js) .stretch-sequence__spacer,
.stretch-sequence__spacer {
  /* sticky still applies in the no-JS case but the spacer height is what
     pins; that's fine — readers just scroll a long, calm section. */
}

.stretch-root:not(.stretch-js) .stretch-sequence__scene {
  position: static;
  min-height: 0;
}

.stretch-root:not(.stretch-js) .stretch-pose {
  position: relative;
  inset: auto;
  opacity: 1;
  transform: none;
  padding: clamp(2.5rem, 7vh, 4.5rem) 0;
  border-bottom: 1px solid var(--st-rule-faint);
}

.stretch-root:not(.stretch-js) .stretch-pose:last-child {
  border-bottom: 0;
}

.stretch-root:not(.stretch-js) .stretch-sequence__count {
  display: none;
}

/* ==========================================================================
   Studio footer — the back page
   The studio note (coda), a practical ledger, and the two working links.
   ========================================================================== */

.stretch-studio {
  position: relative;
  padding: clamp(5rem, 14vh, 9rem) clamp(1.25rem, 5vw, 5rem)
    clamp(3rem, 8vh, 5rem);
  border-top: 1px solid var(--st-rule-faint);
}

.stretch-studio__head {
  max-width: 44rem;
  margin: 0 0 clamp(2.5rem, 6vh, 4rem);
}

.stretch-studio__title {
  margin: 0 0 0.6rem;
  font-family: var(--st-font-kr);
  font-weight: 700;
  font-size: clamp(1.9rem, 4.5vw, 3.2rem);
  line-height: 1.18;
  color: var(--st-ink);
}

.stretch-studio__sub {
  margin: 0;
  font-family: var(--st-font-latin);
  font-style: italic;
  font-size: clamp(1rem, 1.4vw, 1.2rem);
  color: var(--st-ink-soft);
}

.stretch-studio__note {
  max-width: 40rem;
  margin: 0 0 clamp(2.5rem, 6vh, 4rem);
}

.stretch-studio__p {
  margin: 0 0 1.1rem;
}

.stretch-studio__p--en {
  font-family: var(--st-font-latin);
  color: var(--st-ink-soft);
  font-size: 0.96em;
}

.stretch-studio__ledger {
  display: grid;
  gap: clamp(1.2rem, 3vh, 2rem);
  max-width: 44rem;
  margin: 0 0 clamp(2.5rem, 6vh, 4rem);
}

@media (min-width: 720px) {
  .stretch-studio__ledger {
    grid-template-columns: 1fr 1fr;
  }
}

.stretch-studio__ledger div {
  border-top: 1px solid var(--st-rule-faint);
  padding-top: 1rem;
}

.stretch-studio__ledger dt {
  margin: 0 0 0.4rem;
  font-family: var(--st-font-latin);
  font-size: 0.7rem;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--st-clay-deep);
}

.stretch-studio__ledger dd {
  margin: 0;
  font-size: 0.98rem;
  line-height: 1.5;
  color: var(--st-ink);
}

.stretch-studio__end {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem 2rem;
  justify-content: space-between;
  align-items: baseline;
  max-width: 44rem;
  padding-top: 2rem;
  border-top: 1px solid var(--st-rule-faint);
}

.stretch-studio__legal {
  margin: 0;
  font-size: 0.85rem;
  color: var(--st-ink-soft);
}

.stretch-studio__top {
  margin: 0;
}

/* ==========================================================================
   Scroll reveals — JS-gated pre-state, transform/opacity only
   ========================================================================== */

.stretch-js [data-reveal] {
  opacity: 0;
  transform: translateY(18px);
  transition:
    opacity var(--st-reveal-ms) var(--st-ease-breathe),
    transform var(--st-reveal-ms) var(--st-ease-breathe);
  will-change: opacity, transform;
}

.stretch-js [data-reveal].is-visible {
  opacity: 1;
  transform: none;
}

/* ==========================================================================
   Reduced motion — one calm, fully-stretched static page
   - cover: wordmark fully risen and filled, rule grown, no choreography
   - reveals: present, no motion
   - sequence: every pose at full reach, fully written, stacked in flow
     (the no-JS flattening styles above also apply, so the sequence reads
     as a finished poster rather than a pinned animation)
   - breath circles: still, present (no breathing cycle, no parallax)
   - underlines: simply present, no reach
   ========================================================================== */

@media (prefers-reduced-motion: reduce) {
  .stretch-breath__layer {
    animation: none !important;
  }

  .stretch-js .stretch-wordmark__ch {
    animation: none;
    opacity: 1;
    transform: none;
  }

  .stretch-js .stretch-cover__rule {
    animation: none;
    transform: scaleX(1);
  }

  .stretch-js [data-reveal] {
    opacity: 1;
    transform: none;
    transition: none;
  }

  /* When motion is reduced, also flatten the pinned sequence — the JS
     hook still writes --st-scrub but we override the stacking so the page
     reads as a calm document of four fully-held poses. */
  .stretch-js .stretch-sequence__spacer {
    height: auto;
  }

  .stretch-js .stretch-sequence__pin {
    position: relative;
    top: auto;
    height: auto;
  }

  .stretch-js .stretch-sequence__scene {
    position: static;
    min-height: 0;
  }

  .stretch-js .stretch-pose {
    position: relative;
    inset: auto;
    opacity: 1;
    transform: none;
    padding: clamp(2.5rem, 7vh, 4.5rem) 0;
    border-bottom: 1px solid var(--st-rule-faint);
  }

  .stretch-js .stretch-pose:last-child {
    border-bottom: 0;
  }

  .stretch-js .stretch-sequence__count {
    display: none;
  }

  .stretch-js .stretch-sequence__rail {
    position: relative;
    margin-bottom: 1rem;
  }

  /* Glyphs at full stretch, fully opaque (local scrub clamps to 1). */
  .stretch-js .stretch-glyph {
    transform: scaleY(2.8) !important;
    opacity: 1 !important;
  }

  .stretch-link::after,
  .stretch-cover__cta::after {
    transform: scaleX(1);
    transition: none;
  }
}

/* ==========================================================================
   Small-viewport adjustments — composed at 360px, honest in between
   ========================================================================== */

@media (max-width: 560px) {
  .stretch-cover {
    padding: clamp(1.5rem, 4vh, 2.5rem) clamp(1.1rem, 4vw, 1.5rem);
  }

  .stretch-cover__folio {
    font-size: 0.62rem;
  }

  /* The latin wordmark is allowed to scale down hard on phones; the
     korean 늘어 stays the warmer anchor. */
  .stretch-wordmark__latin {
    font-size: clamp(3.4rem, 22vw, 6rem);
  }

  .stretch-wordmark__ko {
    font-size: clamp(2rem, 11vw, 3.4rem);
  }

  .stretch-sequence {
    padding-left: clamp(1.1rem, 4vw, 1.5rem);
    padding-right: clamp(1.1rem, 4vw, 1.5rem);
  }

  /* On small screens the tick labels crowd; keep the ticks, drop labels. */
  .stretch-sequence__tick-label {
    display: none;
  }

  .stretch-pose__name-ko {
    font-size: clamp(3rem, 16vw, 5rem);
  }

  .stretch-pose__name-latin {
    font-size: clamp(1.1rem, 4vw, 1.6rem);
  }

  .stretch-studio__end {
    flex-direction: column;
    align-items: flex-start;
  }
}
